#include<bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1e9+7;
const int SIZE = 1<<20;

ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}
ll mod_inv(ll x) { return mod_pow(x, MOD-2); }

// recursive FWHT
void fwt(int* a, int left, int right, bool forward) {
    if (right - left <= 1) return;
    int mid = (left + right) / 2;
    fwt(a, left, mid, forward);
    fwt(a, mid, right, forward);
    int len = mid - left;
    for (int i = 0; i < len; ++i) {
        int u = a[left + i], v = a[mid + i];
        if (forward) {
            a[left + i] = u + v;
            if (a[left + i] >= MOD) a[left + i] -= MOD;
        } else {
            a[left + i] = u - v;
            if (a[left + i] < 0) a[left + i] += MOD;
        }
    }
}

int main() {
    int n;
    scanf("%d", &n);
    int p[10][10];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            scanf("%d", &p[i][j]);
            p[i][j] = (ll)p[i][j] * mod_inv(100) % MOD;
        }
    if (n < 6) {
        for (int i = n; i < 6; ++i) p[i][i] = 1;
        n = 6;
    }
    int id[64], ki = 0;
    for (int i = 0; i < 64; ++i) if (__builtin_popcount(i) == 3) id[i] = ki++;
    int fullMask = 63;
    vector<int> X(SIZE, 0), Y(SIZE, 0);
    // First section
    for (int i = 0; i < (1<<18); ++i) {
        int m1 = i & fullMask, m2 = (i>>6)&fullMask, m3 = (i>>12)&fullMask;
        ll prob = 1;
        for (int r = 0; r < 3; ++r) {
            int mask = (r==0 ? m1 : (r==1 ? m2 : m3));
            for (int j = 0; j < 6; ++j) {
                if (mask>>j & 1) prob = prob * p[r][j] % MOD;
                else prob = prob * (MOD + 1 - p[r][j]) % MOD;
            }
        }
        int mask = 0;
        for (int a = 0; a < 6; ++a) if (m1>>a & 1)
            for (int b = 0; b < 6; ++b) if (a != b && (m2>>b & 1))
                for (int c = 0; c < 6; ++c) if (a != c && b != c && (m3>>c & 1)) {
                    int triple = (1<<a)|(1<<b)|(1<<c);
                    mask |= 1 << id[triple];
                }
        if (prob >= MOD) prob -= MOD; // redundant but safe
        X[mask] = (X[mask] + prob) % MOD;
    }
    // Second section
    for (int i = 0; i < (1<<18); ++i) {
        int m1 = i & fullMask, m2 = (i>>6)&fullMask, m3 = (i>>12)&fullMask;
        ll prob = 1;
        for (int r = 0; r < 3; ++r) {
            int mask = (r==0 ? m1 : (r==1 ? m2 : m3));
            for (int j = 0; j < 6; ++j) {
                if (mask>>j & 1) prob = prob * p[r+3][j] % MOD;
                else prob = prob * (MOD + 1 - p[r+3][j]) % MOD;
            }
        }
        int mask = 0;
        for (int a = 0; a < 6; ++a) if (m1>>a & 1)
            for (int b = 0; b < 6; ++b) if (a != b && (m2>>b & 1))
                for (int c = 0; c < 6; ++c) if (a != c && b != c && (m3>>c & 1)) {
                    int triple = (1<<a)|(1<<b)|(1<<c);
                    triple ^= fullMask;
                    mask |= 1 << id[triple];
                }
        Y[mask] = (Y[mask] + prob) % MOD;
    }
    fwt(X.data(), 0, SIZE, true);
    fwt(Y.data(), 0, SIZE, true);
    for (int i = 0; i < SIZE; ++i) X[i] = (ll)X[i] * Y[i] % MOD;
    fwt(X.data(), 0, SIZE, false);
    int ans = 0;
    for (int i = 1; i < SIZE; ++i) {
        ans += X[i];
        if (ans >= MOD) ans -= MOD;
    }
    printf("%d\n", ans);
    return 0;
}
